export interface NewApiTokenRecord {
  readonly id: string;
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly tokenHash: string;
  readonly prefix: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

/** Live means not revoked and not yet expired at `now`. Expiry is exclusive. */
function usablePredicate(orgId: OrgId, userId: UserId, now: IsoTimestamp) {
  return and(
    orgPredicate(apiTokens.orgId, orgId),
    eq(apiTokens.userId, userId),
    isNull(apiTokens.revokedAt),
    gt(apiTokens.expiresAt, now),
  );
}

/**
 * Inserts the token only while the owner holds fewer than `limit` usable
 * tokens in the org. The count and the insert share one synchronous
 * transaction, so concurrent creates cannot both slip under the cap.
 * Resolves `null` when the cap is already reached.
 */
export async function insertApiTokenWithinLimit(
  record: NewApiTokenRecord,
  limit: number,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const active = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(usablePredicate(record.orgId, record.userId, record.createdAt))
      .get();

    if ((active?.value ?? 0) >= limit) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: record.id,
        orgId: record.orgId,
        userId: record.userId,
        name: record.name,
        scope: record.scope,
        tokenHash: record.tokenHash,
        prefix: record.prefix,
        expiresAt: record.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: record.createdAt,
        updatedAt: record.createdAt,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/** Looks a token up by the digest of its secret. Callers never see the digest. */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Newest first; ULID ids break ties between tokens created in the same instant. */
export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)),
    )
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id))
    .all();
  return rows.map(toApiToken);
}

export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  revokedAt: IsoTimestamp,
): Promise<ApiToken> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt, updatedAt: revokedAt })
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .returning()
    .get();

  if (!row) throw new Error(`API token ${tokenId} not found in org ${orgId}`);
  return toApiToken(row);
}

/**
 * Revokes every not-yet-revoked token the user holds in the org, expired ones
 * included, and returns the rows it changed. Tokens already revoked keep their
 * original `revokedAt`.
 */
export async function revokeLiveApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
  revokedAt: IsoTimestamp,
): Promise<readonly ApiToken[]> {
  return getDb().transaction((tx) => {
    const live = tx
      .select({ id: apiTokens.id })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, orgId),
          eq(apiTokens.userId, userId),
          isNull(apiTokens.revokedAt),
        ),
      )
      .all();

    return live.map(({ id }) =>
      toApiToken(
        tx
          .update(apiTokens)
          .set({ revokedAt, updatedAt: revokedAt })
          .where(eq(apiTokens.id, id))
          .returning()
          .get(),
      ),
    );
  });
}

export async function touchApiTokenLastUsed(
  tokenId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at, updatedAt: at })
    .where(eq(apiTokens.id, tokenId))
    .run();
}

