/**
 * Personal API tokens: issuing, listing, revoking and authenticating the
 * `tfk_` secrets scripts and CI use to call Taskflow as a member.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, createApiTokenSchema
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { newId } from "@/lib/id";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, orgResource, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const SECRET_PREFIX = "tfk_";
/** Length of the visible head of the secret stored alongside each token. */
const DISPLAY_PREFIX_LENGTH = 12;
const SECRET_BYTES = 32;
/** Usable (not revoked, not expired) tokens one user may hold per organization. */
const MAX_USABLE_TOKENS_PER_USER = 5;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Mints a token and returns its secret exactly once. Only the digest is
 * persisted, so the secret cannot be recovered later.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:write", orgResource(parsed.orgId));
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);
  const expiresAt = toIsoTimestamp(
    new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
  );
  const token = `${SECRET_PREFIX}${randomToken(SECRET_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      id: newId(),
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      tokenHash: hashToken(token),
      prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
      expiresAt,
      createdAt,
    },
    MAX_USABLE_TOKENS_PER_USER,
  );

  if (!apiToken) {
    throw new Error(
      `A user may hold at most ${MAX_USABLE_TOKENS_PER_USER} active API tokens per organization`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

/** Defaults to the actor's own tokens; anyone else's needs `api_token:manage`. */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(actor, "api_token:manage", orgResource(orgId));
  }
  return apiTokenRepo.listApiTokens(orgId, userId);
}

/**
 * Revoking is idempotent: an already-revoked token comes back unchanged and
 * is not audited a second time.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  const revokedAt = toIsoTimestamp(new Date());
  const revoked = await apiTokenRepo.revokeApiToken(orgId, tokenId, revokedAt);

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    userId: revoked.userId,
  });

  return revoked;
}

/**
 * Resolves a presented secret to the actor it acts as, or `null` when it
 * cannot. A `read` token acts as `viewer`; a `write` token acts with the
 * member's role as it stands at the time of the call.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const record = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (!record || record.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  // Expiry is exclusive: the token stops working at exactly `expiresAt`.
  if (record.expiresAt <= now) return null;

  const member = await resolveActor(record.userId, record.orgId);
  if (!member) return null;

  const org = await orgRepo.findOrgById(record.orgId);
  if (!org || org.archivedAt !== null) return null;

  await apiTokenRepo.touchApiTokenLastUsed(record.id, now);

  return {
    userId: record.userId,
    orgId: record.orgId,
    role: record.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Removing a member revokes every token they hold in that org. The remover is
 * the actor on each resulting audit row, and tokens in other orgs are untouched.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const revokedAt = toIsoTimestamp(new Date());
    const revoked = await apiTokenRepo.revokeLiveApiTokensForUser(
      payload.orgId,
      payload.userId,
      revokedAt,
    );

    for (const token of revoked) {
      await emit("api_token.revoked", {
        orgId: payload.orgId,
        actorId: payload.actorId,
        occurredAt: revokedAt,
        tokenId: token.id,
        userId: token.userId,
      });
    }
  });
}

