  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(actor, "api_token:manage", orgResource(orgId));
  }
  return apiTokenRepo.listApiTokens(orgId, userId);
}

/**
 * Revoking is idempotent: an already-revoked token comes back unchanged and
 * is not audited a second time.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  const revokedAt = toIsoTimestamp(new Date());
  const revoked = await apiTokenRepo.revokeApiToken(orgId, tokenId, revokedAt);

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    userId: revoked.userId,
  });

  return revoked;
}

/**
 * Resolves a presented secret to the actor it acts as, or `null` when it
 * cannot. A `read` token acts as `viewer`; a `write` token acts with the
 * member's role as it stands at the time of the call.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  const record = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (!record || record.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  // Expiry is exclusive: the token stops working at exactly `expiresAt`.
  if (record.expiresAt <= now) return null;

  const member = await resolveActor(record.userId, record.orgId);
  if (!member) return null;

  const org = await orgRepo.findOrgById(record.orgId);
  if (!org || org.archivedAt !== null) return null;

  await apiTokenRepo.touchApiTokenLastUsed(record.id, now);

  return {
    userId: record.userId,
    orgId: record.orgId,
    role: record.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Removing a member revokes every token they hold in that org. The remover is
 * the actor on each resulting audit row, and tokens in other orgs are untouched.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const revokedAt = toIsoTimestamp(new Date());
    const revoked = await apiTokenRepo.revokeLiveApiTokensForUser(
      payload.orgId,
      payload.userId,
      revokedAt,
    );

    for (const token of revoked) {
      await emit("api_token.revoked", {
        orgId: payload.orgId,
        actorId: payload.actorId,
        occurredAt: revokedAt,
        tokenId: token.id,
        userId: token.userId,
      });
    }
  });
}

