/**
 * Personal API tokens: issuing, listing, revoking and authenticating the
 * `tfk_` secrets scripts and CI use to call Taskflow as a member.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, createApiTokenSchema
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { newId } from "@/lib/id";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, orgResource, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

const SECRET_PREFIX = "tfk_";
/** Length of the visible head of the secret stored alongside each token. */
const DISPLAY_PREFIX_LENGTH = 12;
const SECRET_BYTES = 32;
/** Usable (not revoked, not expired) tokens one user may hold per organization. */
const MAX_USABLE_TOKENS_PER_USER = 5;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Mints a token and returns its secret exactly once. Only the digest is
 * persisted, so the secret cannot be recovered later.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:write", orgResource(parsed.orgId));
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);
  const expiresAt = toIsoTimestamp(
    new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
  );
  const token = `${SECRET_PREFIX}${randomToken(SECRET_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      id: newId(),
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      tokenHash: hashToken(token),
      prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
      expiresAt,
      createdAt,
    },
    MAX_USABLE_TOKENS_PER_USER,
  );

  if (!apiToken) {
    throw new Error(
      `A user may hold at most ${MAX_USABLE_TOKENS_PER_USER} active API tokens per organization`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

