import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { ZodError } from "zod";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as apiTokenService from "@/server/services/api-token-service";
import * as memberService from "@/server/services/member-service";
import * as memberRepo from "@/server/repositories/member-repository";
import { getDb, activityEvents } from "@/server/db";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import { eq } from "drizzle-orm";

let cleanup: () => void;
beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});
afterAll(() => {
  unregisterEventHandlers();
  cleanup();
  vi.useRealTimers();
});

describe("scratch api tokens", () => {
  it("creates read tokens with the right shape and no secret in the row", async () => {
    const t = await createTenant("scratch-create", "growth");
    const { token, apiToken } = await apiTokenService.createApiToken(t.actors.viewer, {
      orgId: t.org.id, name: "  ci  ", scope: "read", expiresInDays: 7,
    });
    expect(token.startsWith("tfk_")).toBe(true);
    expect(apiToken.prefix).toBe(token.slice(0, 12));
    expect(apiToken.name).toBe("ci");
    expect(Object.keys(apiToken)).not.toContain("tokenHash");
    const ms = Date.parse(apiToken.expiresAt) - Date.parse(apiToken.createdAt);
    expect(ms).toBe(7 * 24 * 3600 * 1000);
    expect(apiToken.lastUsedAt).toBeNull();
    expect(apiToken.revokedAt).toBeNull();
    const actor = await apiTokenService.authenticateApiToken(token);
    expect(actor).toEqual({ userId: t.userIds.viewer, orgId: t.org.id, role: "viewer" });
    const rows = getDb().select().from(activityEvents).where(eq(activityEvents.action, "api_token.created")).all();
    expect(rows.length).toBe(1);
    expect(JSON.stringify(rows[0])).not.toContain(token);
  });

  it("enforces write role, tenant scope and zod validation", async () => {
    const t = await createTenant("scratch-guards", "growth");
    await expect(apiTokenService.createApiToken(t.actors.viewer, {
      orgId: t.org.id, name: "w", scope: "write", expiresInDays: 1,
    })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "   ", scope: "read", expiresInDays: 1,
    })).rejects.toBeInstanceOf(ZodError);
    await expect(apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "x", scope: "read", expiresInDays: 366,
    })).rejects.toBeInstanceOf(ZodError);
    await expect(apiTokenService.listApiTokens(t.actors.member, "01HZZZZZZZZZZZZZZZZZZZZZZZ" as never))
      .rejects.toBeInstanceOf(TenantScopeError);
  });

  it("caps usable tokens at five per user and frees a slot on revoke", async () => {
    const t = await createTenant("scratch-cap", "growth");
    const made = [];
    for (let i = 0; i < 5; i++) {
      made.push((await apiTokenService.createApiToken(t.actors.member, {
        orgId: t.org.id, name: `n${i}`, scope: "write", expiresInDays: 30,
      })).apiToken);
    }
    await expect(apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "six", scope: "read", expiresInDays: 30,
    })).rejects.toThrow();
    // Another user has their own allowance.
    await apiTokenService.createApiToken(t.actors.viewer, {
      orgId: t.org.id, name: "other", scope: "read", expiresInDays: 30,
    });
    await apiTokenService.revokeApiToken(t.actors.member, t.org.id, made[0]!.id);
    await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "again", scope: "read", expiresInDays: 30,
    });
    const list = await apiTokenService.listApiTokens(t.actors.member, t.org.id);
    expect(list.length).toBe(7);
    // Newest first.
    expect(list[0]!.name).toBe("again");
  });

  it("re-revoke is a no-op, list needs admin for others, expiry is exclusive", async () => {
    const t = await createTenant("scratch-revoke", "growth");
    const { token, apiToken } = await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "r", scope: "write", expiresInDays: 1,
    });
    const first = await apiTokenService.revokeApiToken(t.actors.member, t.org.id, apiToken.id);
    const second = await apiTokenService.revokeApiToken(t.actors.member, t.org.id, apiToken.id);
    expect(second.revokedAt).toBe(first.revokedAt);
    expect(await apiTokenService.authenticateApiToken(token)).toBeNull();
    await expect(apiTokenService.listApiTokens(t.actors.viewer, t.org.id, t.userIds.member))
      .rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(apiTokenService.revokeApiToken(t.actors.viewer, t.org.id, "nope"))
      .rejects.toThrow(/not found/);

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2030-01-01T00:00:00.000Z"));
    const { token: t2, apiToken: a2 } = await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "e", scope: "read", expiresInDays: 1,
    });
    vi.setSystemTime(new Date(Date.parse(a2.expiresAt) - 1));
    expect(await apiTokenService.authenticateApiToken(t2)).not.toBeNull();
    vi.setSystemTime(new Date(Date.parse(a2.expiresAt)));
    expect(await apiTokenService.authenticateApiToken(t2)).toBeNull();
    vi.useRealTimers();
  });

  it("write tokens follow role changes; removal revokes and audits with remover", async () => {
    const t = await createTenant("scratch-remove", "growth");
    const { token } = await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "w", scope: "write", expiresInDays: 30,
    });
    const { token: readTok } = await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "rd", scope: "read", expiresInDays: 30,
    });
    const memberRow = await memberRepo.findMember(t.org.id, t.userIds.member);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: memberRow!.id });
    expect(await apiTokenService.authenticateApiToken(token)).toBeNull();
    expect(await apiTokenService.authenticateApiToken(readTok)).toBeNull();
    const revokedRows = getDb().select().from(activityEvents).where(eq(activityEvents.action, "api_token.revoked")).all();
    expect(revokedRows.length).toBe(2);
    expect(revokedRows.every((r) => r.actorId === t.userIds.owner)).toBe(true);
  });
});

