    const list = await apiTokenService.listApiTokens(t.actors.member, t.org.id);
    expect(list.length).toBe(6);
    // Newest first.
    expect(list[0]!.name).toBe("again");
  });

  it("re-revoke is a no-op, list needs admin for others, expiry is exclusive", async () => {
    const t = await createTenant("scratch-revoke", "growth");
    const { token, apiToken } = await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "r", scope: "write", expiresInDays: 1,
    });
    const first = await apiTokenService.revokeApiToken(t.actors.member, t.org.id, apiToken.id);
    const second = await apiTokenService.revokeApiToken(t.actors.member, t.org.id, apiToken.id);
    expect(second.revokedAt).toBe(first.revokedAt);
    expect(await apiTokenService.authenticateApiToken(token)).toBeNull();
    await expect(apiTokenService.listApiTokens(t.actors.viewer, t.org.id, t.userIds.member))
      .rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(apiTokenService.revokeApiToken(t.actors.viewer, t.org.id, "nope"))
      .rejects.toThrow(/not found/);

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2030-01-01T00:00:00.000Z"));
    const { token: t2, apiToken: a2 } = await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "e", scope: "read", expiresInDays: 1,
    });
    vi.setSystemTime(new Date(Date.parse(a2.expiresAt) - 1));
    expect(await apiTokenService.authenticateApiToken(t2)).not.toBeNull();
    vi.setSystemTime(new Date(Date.parse(a2.expiresAt)));
    expect(await apiTokenService.authenticateApiToken(t2)).toBeNull();
    vi.useRealTimers();
  });

  it("write tokens follow role changes; removal revokes and audits with remover", async () => {
    const t = await createTenant("scratch-remove", "growth");
    const { token } = await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "w", scope: "write", expiresInDays: 30,
    });
    const { token: readTok } = await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id, name: "rd", scope: "read", expiresInDays: 30,
    });
    const memberRow = await memberRepo.findMember(t.org.id, t.userIds.member);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: memberRow!.id });
    expect(await apiTokenService.authenticateApiToken(token)).toBeNull();
    expect(await apiTokenService.authenticateApiToken(readTok)).toBeNull();
    const revokedRows = getDb().select().from(activityEvents).where(and(eq(activityEvents.action, "api_token.revoked"), eq(activityEvents.orgId, t.org.id))).all();
    expect(revokedRows.length).toBe(2);
    expect(revokedRows.every((r) => r.actorId === t.userIds.owner)).toBe(true);
  });
});
